      const k2u = du(t + h / 2, ui + (h / 2) * k1u), k2c = dc(ui + (h / 2) * k1u);
      const k3u = du(t + h / 2, ui + (h / 2) * k2u), k3c = dc(ui + (h / 2) * k2u);
      const k4u = du(t + h, ui + h * k3u), k4c = dc(ui + h * k3u);
