  wheel.position.z = -(0.05 + ALARM_SET_T / 2); // band −0.05..−0.23 (dialFace local; ALARM_SET_Z is this plane in world)
  alarmSetWheelMesh = wheel;   // TODO 15: the chain solve's datum
  alarmSetWheelGroup.add(wheel);
