    span.textContent = `${c.label} \u2014 \u26a0 ${c.warns[0]}${c.warns.length > 1 ? ` (+${c.warns.length - 1} more)` : ''}`;
    applyRow.style.display = ''; // a WARNED spec may still be applied — boot asserts repeat the verdict in amber
