    reconfGhost.rotation.z = az;
    reconfGhost.children.forEach((ch) => ch.material.color.set(conflict ? 0xe08888 : 0xbfeee2));
    const vAz = rk.toValue ? rk.toValue(az) : az;
    const deg = ((vAz * 180 / Math.PI) % 360 + 360) % 360;
