  setAlarmCrownOut(v) { alarmCrownOut = !!v; },
  setBarrelWindTurns(v) { barrelWindTurns = clamp(v, 0, RESERVE_BARREL_TURNS); },
  // Zero every PERSISTENT user input, returning the mechanism to its as-booted
